        "tr": {
          "auteur": "Diyanet İşleri Başkanlığı",
          "texte": "Gerçeği batılın başına çarparız ve onun beynini parçalar; böylece batıl ortadan kalkar. Allah'a yakıştırdığınız vasıflardan ötürü yazıklar olsun size"
        }
