        "tr": {
          "auteur": "Diyanet İşleri Başkanlığı",
          "texte": "Senden önce gönderdiğimiz her peygambere: \"Benden başka tanrı yoktur, Bana kulluk edin\" diye vahyetmişizdir"
        }
