      "ar": "وَنُوحًا إِذْ نَادَىٰ مِن قَبْلُ فَاسْتَجَبْنَا لَهُ فَنَجَّيْنَٰهُ وَأَهْلَهُ مِنَ الْكَرْبِ الْعَظِيمِ",
